CREATE TABLE procedure_types(id uuid PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE worker_qualifications(user_id uuid NOT NULL REFERENCES users(id),procedure_type_id uuid NOT NULL REFERENCES procedure_types(id),active boolean NOT NULL DEFAULT true,valid_until date,updated_by uuid NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,procedure_type_id));
ALTER TABLE products ADD COLUMN details jsonb NOT NULL DEFAULT '{}';
ALTER TABLE product_steps ADD COLUMN production jsonb NOT NULL DEFAULT '{}';
ALTER TABLE tasks ADD COLUMN production jsonb NOT NULL DEFAULT '{}',ADD COLUMN assigned_worker_id uuid REFERENCES users(id),ADD COLUMN assigned_station_id uuid REFERENCES records(id),ADD COLUMN assigned_device_id uuid REFERENCES records(id);
CREATE TABLE production_routes(id uuid PRIMARY KEY,product_id uuid REFERENCES products(id),name text NOT NULL,steps jsonb NOT NULL,active boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX production_routes_name ON production_routes(product_id,name) NULLS NOT DISTINCT;
ALTER TABLE work_orders ADD COLUMN route_id uuid REFERENCES production_routes(id),ADD COLUMN route_name text;
ALTER TABLE reports ADD COLUMN device_id uuid REFERENCES records(id),ADD COLUMN complete_adjustment integer NOT NULL DEFAULT 0,ADD COLUMN manager_reason text;
CREATE TABLE station_execution(station_id uuid PRIMARY KEY REFERENCES records(id),procedure_type_id uuid REFERENCES procedure_types(id),device_id uuid REFERENCES records(id),state text NOT NULL DEFAULT 'off_duty' CHECK(state IN ('off_duty','on_duty','disabled')),worker_id uuid REFERENCES users(id),current_report_id uuid REFERENCES reports(id),idle_since timestamptz,idle_threshold_minutes integer NOT NULL DEFAULT 60 CHECK(idle_threshold_minutes BETWEEN 1 AND 1440),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((state='on_duty')=(worker_id IS NOT NULL)),CHECK(current_report_id IS NULL OR state='on_duty'));
CREATE UNIQUE INDEX station_exclusive_device ON station_execution(device_id) WHERE device_id IS NOT NULL AND state<>'disabled';
CREATE TABLE station_events(id uuid PRIMARY KEY,station_id uuid NOT NULL REFERENCES records(id),worker_id uuid REFERENCES users(id),actor_id uuid REFERENCES users(id),event text NOT NULL,reason text NOT NULL DEFAULT '',started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,report_id uuid REFERENCES reports(id));
CREATE INDEX station_events_scope ON station_events(station_id,started_at DESC);
CREATE UNIQUE INDEX station_open_idle ON station_events(station_id) WHERE event='no_material' AND ended_at IS NULL;
CREATE TABLE scrap_types(id uuid PRIMARY KEY,code text NOT NULL UNIQUE,name text NOT NULL,deductible boolean NOT NULL DEFAULT true,active boolean NOT NULL DEFAULT true);
ALTER TABLE scraps ADD COLUMN scrap_type_id uuid REFERENCES scrap_types(id),ADD COLUMN responsible_report_id uuid REFERENCES reports(id),ADD COLUMN deductible boolean NOT NULL DEFAULT false,ADD COLUMN deduction_unit_price numeric(18,4) NOT NULL DEFAULT 0 CHECK(deduction_unit_price>=0),ADD COLUMN reward_unit_price numeric(18,4) NOT NULL DEFAULT 0 CHECK(reward_unit_price>=0),ADD COLUMN approval_mode text CHECK(approval_mode IN ('manual','automatic')),ADD COLUMN auto_review_reason text;
CREATE TABLE production_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),scrap_auto_review boolean NOT NULL DEFAULT false,scrap_max_amount numeric(18,2) NOT NULL DEFAULT 2000 CHECK(scrap_max_amount>=0),revision integer NOT NULL DEFAULT 1,updated_by uuid REFERENCES users(id));
INSERT INTO production_settings(id) VALUES(true);
ALTER TABLE payroll DROP CONSTRAINT payroll_source_type_check;
ALTER TABLE payroll ADD CONSTRAINT payroll_source_type_check CHECK(source_type IN ('piece','hours','reward','penalty','scrap-penalty','scrap-reward','piece-adjustment'));
DROP INDEX reports_active_worker;
CREATE UNIQUE INDEX reports_active_unassigned_worker ON reports(worker_id) WHERE status IN ('received','working') AND workstation_id IS NULL;
ALTER TABLE reports ADD CONSTRAINT reports_adjusted_quantity CHECK(quantity+complete_adjustment>=0);
ALTER TABLE sales_orders ADD COLUMN name text NOT NULL DEFAULT '',ADD COLUMN priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('normal','urgent')),ADD COLUMN revision integer NOT NULL DEFAULT 1,ADD COLUMN completed_at timestamptz;
ALTER TABLE sales_order_items ADD COLUMN notes text NOT NULL DEFAULT '';
